USE RecruitPlatform_Target;

TRUNCATE TABLE dbo.SkillCategory;

INSERT INTO dbo.SkillCategory (
    ID,
    CategoryName,
    Deleted
)
SELECT
    sc.category_id  AS ID,
    sc.name         AS CategoryName,
    sc.deleted      AS Deleted
FROM Migration_Staging.mid.SkillCategories sc;

USE RecruitPlatform_Target;

TRUNCATE TABLE dbo.PositionType;

INSERT INTO dbo.PositionType (
    ID,
    Type
)
SELECT
    ROW_NUMBER() OVER (ORDER BY j.employment_type)                           AS ID,
    UPPER(LEFT(j.employment_type, 1)) + SUBSTRING(j.employment_type, 2, 50)  AS Type
FROM (SELECT DISTINCT employment_type FROM Migration_Staging.mid.Jobs WHERE employment_type IS NOT NULL) j;

USE RecruitPlatform_Target;

TRUNCATE TABLE dbo.Deal_Stage;

DELETE FROM dbo.MigrationRejects WHERE target_table = N'Deal_Stage';

INSERT INTO dbo.MigrationRejects (target_table, source_key, action, reason)
SELECT N'Deal_Stage', CAST(TRY_CAST(pl.placement_id AS INT) AS NVARCHAR(200)), N'rejected', N'not a migrated candidate (a contact, a removed duplicate or missing)'
FROM Migration_Staging.mid.Placements pl
WHERE NOT (EXISTS (SELECT 1 FROM Migration_Staging.mid.Candidates x WHERE x.candidate_id = pl.candidate_id));

INSERT INTO dbo.Deal_Stage (
    ID,
    DealID,
    Stage
)
SELECT
    TRY_CAST(pl.placement_id AS INT)  AS ID,
    TRY_CAST(pl.placement_id AS INT)  AS DealID,
    'Won'                             AS Stage
FROM Migration_Staging.mid.Placements pl
WHERE (EXISTS (SELECT 1 FROM Migration_Staging.mid.Candidates x WHERE x.candidate_id = pl.candidate_id));

USE RecruitPlatform_Target;

TRUNCATE TABLE dbo.Sources;

INSERT INTO dbo.Sources (
    ID,
    Name
)
SELECT
    CAST(ROW_NUMBER() OVER (ORDER BY s.source) AS NVARCHAR(50))  AS ID,
    UPPER(LEFT(s.source, 1)) + SUBSTRING(s.source, 2, 50)        AS Name
FROM (SELECT DISTINCT source FROM Migration_Staging.mid.Candidates WHERE source IS NOT NULL) s;

USE RecruitPlatform_Target;

TRUNCATE TABLE dbo.Currencies;

INSERT INTO dbo.Currencies (
    CurrencyID,
    CurrencyCode
)
SELECT
    ROW_NUMBER() OVER (ORDER BY cu.currency)  AS CurrencyID,
    cu.currency                               AS CurrencyCode
FROM (SELECT DISTINCT currency FROM Migration_Staging.mid.Invoices WHERE currency IS NOT NULL) cu;
